import{_ as n,C as s,o as e,c as o,a2 as l,b as i,w as a,a as d,E as g,a3 as E}from"./chunks/framework.BBdhqAg0.js";const C="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",u=JSON.parse('{"title":"계약 실적 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/index.md","filePath":"sales/index.md","lastUpdated":1793112345000}'),B={name:"sales/index.md"};function A(x,t,c,h,f,_){const r=s("Mermaid");return e(),o("div",null,[t[1]||(t[1]=l('<h1 id="계약-실적-관리" tabindex="-1">계약 실적 관리 <a class="header-anchor" href="#계약-실적-관리" aria-label="Permalink to &quot;계약 실적 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+C+'" alt="계약 실적 및 영업 담당자 매핑 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/index.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>계약 실적 관리</strong> 페이지는 프로젝트에서 체결된 분양 계약 건에 대해 담당 영업 인력(분양상담사, 소속 팀장) 및 외부 공인중개사(MGM)를 매핑하고, 실시간 영업 배정률과 성과 실적을 추적 관리하는 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [분양 대행 관리] → [계약 실적 관리]**를 선택하여 접속합니다.</li></ul>',4)),(e(),i(E,null,{default:a(()=>[g(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EB%B6%84%EC%96%91%20%EA%B3%84%EC%95%BD%20%EC%B2%B4%EA%B2%B0%3Cbr%3E(%EA%B3%84%EC%95%BD%20%EA%B4%80%EB%A6%AC%20%EC%8B%9C%EC%8A%A4%ED%85%9C%20%EC%97%B0%EB%8F%99)%22%5D%20--%3E%20B%5B%222.%20%EC%98%81%EC%97%85%20%EB%8B%B4%EB%8B%B9%EC%9E%90%20%EB%A7%A4%ED%95%91%3Cbr%3E(%EC%83%81%EB%8B%B4%EC%82%AC%C2%B7%EC%86%8C%EC%86%8D%ED%8C%80%C2%B7%EC%88%98%EC%88%98%EB%A3%8C%EC%A0%95%EC%B1%85%20%EC%A7%80%EC%A0%95)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20MGM%20%EC%86%8C%EA%B0%9C%20%EC%A0%95%EB%B3%B4%20%EC%97%B0%EA%B3%84%3Cbr%3E(%EA%B3%B5%EC%9D%B8%EC%A4%91%EA%B0%9C%EC%82%AC%20%EC%83%81%ED%98%B8%C2%B7%EC%97%B0%EB%9D%BD%EC%B2%98%20%EB%93%B1%EB%A1%9D)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%93%8A%20%EC%88%98%EC%88%98%EB%A3%8C%20%EC%A0%95%EC%82%B0%20%ED%9A%8C%EC%B0%A8%20%EB%B0%98%EC%98%81%3Cbr%3E(%EC%A7%81%EC%B1%85%EB%B3%84%20%EC%9D%B8%EC%84%BC%ED%8B%B0%EB%B8%8C%20%EC%9E%90%EB%8F%99%20%EC%82%B0%EC%B6%9C)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-개요-및-비즈니스-연계" tabindex="-1">1. 개요 및 비즈니스 연계 <a class="header-anchor" href="#_1-개요-및-비즈니스-연계" aria-label="Permalink to &quot;1. 개요 및 비즈니스 연계&quot;">​</a></h2><p>프로젝트에서 체결되는 모든 분양 계약을 영업 조직과 유기적으로 연결하여 누가 어떤 계약을 유치했는지 실적을 투명하게 관리합니다.</p><ul><li>계약 건별 담당 상담사와 소속 팀, 적용할 수수료 정책(R값), 성과 인정일을 지정합니다.</li><li>외부 공인중개사가 고객을 알선한 경우 MGM 소개 정보를 등록하여 소개 수수료 지급 근거를 마련합니다.</li><li>본 화면에서 매핑된 데이터는 향후 <strong><a href="/sales/settlement.html">수수료 정산 관리</a></strong> 시 개인별·대행사별 인센티브를 산출하는 핵심 원천 데이터가 됩니다.</li></ul><h2 id="_2-주요-기능" tabindex="-1">2. 주요 기능 <a class="header-anchor" href="#_2-주요-기능" aria-label="Permalink to &quot;2. 주요 기능&quot;">​</a></h2><ul><li><strong>실적 KPI 대시보드</strong>: 프로젝트 전체 계약 건수, 영업 담당자 배정 건수, 배정률(%), MGM 연계 건수 실시간 집계</li><li><strong>계약 실적 대장 조회</strong>: 계약 정보(일련번호, 계약자명, 유니트 동호수)와 매핑된 영업 인력 현황 통합 조회</li><li><strong>다차원 필터링 및 검색</strong>: 배정 상태(전체/배정 완료/미배정), 소속 팀, 담당 상담사별 필터 및 계약자/동호수 키워드 검색</li><li><strong>담당자 배정 및 수정</strong>: 미배정 계약에 대한 신규 영업 담당자 배정 또는 기 배정된 담당자/정책/MGM 정보 수정</li></ul><h2 id="_3-화면-구성-및-조작-가이드" tabindex="-1">3. 화면 구성 및 조작 가이드 <a class="header-anchor" href="#_3-화면-구성-및-조작-가이드" aria-label="Permalink to &quot;3. 화면 구성 및 조작 가이드&quot;">​</a></h2><h3 id="_1-상단-실적-kpi-대시보드" tabindex="-1">1. 상단 실적 KPI 대시보드 <a class="header-anchor" href="#_1-상단-실적-kpi-대시보드" aria-label="Permalink to &quot;1. 상단 실적 KPI 대시보드&quot;">​</a></h3><p>선택된 프로젝트의 분양 계약 및 영업 인력 배정 진척도를 한눈에 파악할 수 있는 요약 카드를 제공합니다.</p><ul><li><strong>총 분양 계약 건수</strong>: 현재 프로젝트에서 체결된 총 계약 건수</li><li><strong>영업 담당 배정 건수</strong>: 영업 인력이 배정 완료된 계약 건수</li><li><strong>담당자 배정률</strong>: 총 계약 대비 영업 담당자 배정 완료 비율(%)</li><li><strong>MGM 연계 계약 건수</strong>: 공인중개사 소개(MGM)로 체결된 계약 건수</li></ul><h3 id="_2-목록-제어-및-검색-툴바" tabindex="-1">2. 목록 제어 및 검색 툴바 <a class="header-anchor" href="#_2-목록-제어-및-검색-툴바" aria-label="Permalink to &quot;2. 목록 제어 및 검색 툴바&quot;">​</a></h3><ul><li><strong>매핑 상태 필터</strong>: <code>전체 계약</code>, <code>배정 완료 계약</code>, <code>미배정 계약</code> 선택</li><li><strong>소속 팀 필터</strong>: 특정 영업 본부 또는 팀으로 필터링</li><li><strong>담당 상담사 필터</strong>: 특정 영업 상담사로 필터링</li><li><strong>통합 검색창</strong>: 계약자명, 동호수, 계약 일련번호, 상담사명 등으로 빠른 검색</li><li><strong>[담당자 배정] 버튼</strong>: 신규로 계약과 영업 담당자를 매핑하는 팝업 호출</li></ul><h3 id="_3-계약-실적-영업-담당자-매핑-대장-테이블" tabindex="-1">3. 계약 실적 &amp; 영업 담당자 매핑 대장 테이블 <a class="header-anchor" href="#_3-계약-실적-영업-담당자-매핑-대장-테이블" aria-label="Permalink to &quot;3. 계약 실적 &amp; 영업 담당자 매핑 대장 테이블&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>계약 정보</strong></td><td style="text-align:left;">계약 일련번호, 계약자 성명, 동호수 및 유니트 평형 정보</td></tr><tr><td style="text-align:left;"><strong>담당 영업직원</strong></td><td style="text-align:left;">계약을 유치한 담당 분양상담사 성명 (미배정 시 붉은색 배지 표시)</td></tr><tr><td style="text-align:left;"><strong>소속 팀</strong></td><td style="text-align:left;">담당 상담사가 소속된 영업 본부 및 팀명</td></tr><tr><td style="text-align:left;"><strong>적용 수수료 정책</strong></td><td style="text-align:left;">해당 계약에 적용될 수수료 정책(R값) 명칭</td></tr><tr><td style="text-align:left;"><strong>성과 인정일</strong></td><td style="text-align:left;">영업 실적으로 공식 인정되는 기준 일자</td></tr><tr><td style="text-align:left;"><strong>MGM 연계 정보</strong></td><td style="text-align:left;">연계된 공인중개사/소개자 상호 및 연락처 (해당 시 표출)</td></tr><tr><td style="text-align:left;"><strong>관리 액션</strong></td><td style="text-align:left;"><code>[수정]</code> (기존 배정 정보 변경) 또는 <code>[배정하기]</code> (신규 담당자 지정)</td></tr></tbody></table><h3 id="_4-영업-담당자-배정-수정-팝업" tabindex="-1">4. 영업 담당자 배정/수정 팝업 <a class="header-anchor" href="#_4-영업-담당자-배정-수정-팝업" aria-label="Permalink to &quot;4. 영업 담당자 배정/수정 팝업&quot;">​</a></h3><p>계약 건에 영업 담당자를 연결하거나 기존 매핑 정보를 수정하는 입력 팝업창입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">입력 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>대상 계약 선택</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">담당자를 지정할 분양 계약 건 선택 (미배정 계약 우선 표출)</td></tr><tr><td style="text-align:left;"><strong>담당 영업 상담사</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">계약을 성사시킨 영업 인력(상담사) 선택</td></tr><tr><td style="text-align:left;"><strong>소속 팀</strong></td><td style="text-align:center;">자동/선택</td><td style="text-align:left;">상담사 선택 시 소속 팀이 자동 연동되며, 필요 시 수동 변경 가능</td></tr><tr><td style="text-align:left;"><strong>수수료 정책</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 계약에 적용할 수수료 정책 기준표 선택</td></tr><tr><td style="text-align:left;"><strong>영업 성과 인정일</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">실적으로 인정할 일자 (달력 입력)</td></tr><tr><td style="text-align:left;"><strong>MGM 성명/상호</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">고객을 소개한 외부 공인중개사 상호 또는 성명</td></tr><tr><td style="text-align:left;"><strong>MGM 연락처</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">공인중개사 휴대전화 번호</td></tr><tr><td style="text-align:left;"><strong>비고</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">계약 배정 관련 특이사항 및 메모</td></tr></tbody></table><h2 id="_4-신입사원을-위한-실무-가이드" tabindex="-1">4. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_4-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;4. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 정산 전 &#39;미배정 계약&#39; 제로(0) 만들기</strong>: <ul><li>정산 회차를 마감하기 전, 상단 필터에서 **&#39;미배정 계약&#39;**을 선택하여 담당 영업 인력이 빠진 계약 건이 없는지 확인하십시오. 담당자가 매핑되지 않은 계약은 수수료 정산 집계에서 누락되어 상담사 성과급이 미지급될 수 있습니다.</li></ul></li><li><strong>💡 MGM(공인중개사 소개료) 등록 주의사항</strong>: <ul><li>외부 공인중개사(MGM) 소개 건은 고객 상담 카드나 청약 접수증에 기재된 중개업소 상호, 공인중개사 성명, 등록번호를 정확히 확인하고 입력하십시오. 추후 중개수수료 세금계산서 발행 및 지급 증빙으로 활용됩니다.</li></ul></li></ul>',18))])}const b=n(B,[["render",A]]);export{u as __pageData,b as default};
